class SimpleLruCache<K, V> {
    private final int capacity;
    private final HashMap<K, V> data = new HashMap<>();
    private final LinkedList<K> usageOrder = new LinkedList<>();

    SimpleLruCache(int capacity) { this.capacity = capacity; }

    V get(K key) {
        if (!data.containsKey(key)) return null;
        usageOrder.remove(key);
        usageOrder.addLast(key);
        return data.get(key);
    }

    void put(K key, V value) {
        if (data.containsKey(key)) usageOrder.remove(key);
        else if (data.size() >= capacity) {
            K oldest = usageOrder.removeFirst();
            data.remove(oldest);
        }
        data.put(key, value);
        usageOrder.addLast(key);
    }
}

