Map<Integer, Long> memo = new HashMap<>();

System.out.println("fib(50) = " + fib(50, memo));

static long fib(int n, Map<Integer, Long> memo) {
    if (n <= 1) return n;
    if (memo.containsKey(n)) return memo.get(n);
    long result = fib(n - 1, memo) + fib(n - 2, memo);
    memo.put(n, result);
    return result;
}

