class Product {
    String name; double price;
    Product(String name, double price) { this.name = name; this.price = price; }
    double getPrice() { return price; }
}

class Inventory {
    private final Map<String, Integer> quantities = new HashMap<>();
    private final Map<String, Product> products = new HashMap<>();

    void addStock(String name, double price, int qty) {
        products.putIfAbsent(name, new Product(name, price));
        quantities.merge(name, qty, Integer::sum);
    }

    void removeStock(String name, int qty) {
        int current = quantities.getOrDefault(name, 0);
        int updated = current - qty;
        if (updated <= 0) {
            quantities.remove(name);
            products.remove(name);
        } else {
            quantities.put(name, updated);
        }
    }

    double totalValue() {
        double total = 0;
        for (Map.Entry<String, Integer> entry : quantities.entrySet()) {
            total += products.get(entry.getKey()).getPrice() * entry.getValue();
        }
        return total;
    }
}

